/**
 * Saku's service worker.
 *
 * Hand-written rather than generated by `next-pwa`/workbox: what this app actually needs from a
 * service worker is installability and a `push` handler, and a precache manifest over a wallet
 * whose every screen reads live chain and database state would mostly serve stale money.
 * Nothing is cached here on purpose — an offline balance is a wrong balance.
 *
 * Kept in `public/` so it is served from the origin root and therefore scopes the whole app.
 */

self.addEventListener('install', () => {
  // No precache to build, so take over immediately instead of waiting for every tab to close.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  // A push with no payload still means *something* happened — show the generic line rather than
  // dropping it, since some push services strip payloads on delivery retries.
  let payload = { title: 'Saku', body: 'You have a new notification', url: '/notifications' };

  if (event.data) {
    try {
      payload = { ...payload, ...event.data.json() };
    } catch {
      payload.body = event.data.text() || payload.body;
    }
  }

  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      // A tag per event type collapses a burst of the same kind into one banner instead of a
      // stack of near-identical ones.
      tag: payload.tag || 'saku',
      renotify: true,
      data: { url: payload.url || '/notifications' },
    })
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = event.notification.data?.url || '/notifications';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      // Focus an existing tab and navigate it — opening a second copy of a wallet the user
      // already has open is disorienting.
      for (const client of clients) {
        if ('focus' in client) {
          client.navigate(target).catch(() => {});
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    })
  );
});
